// BesinAI veri/bilgi tabani — otomatik bölündü (tek blade -> modüller). Kaynak: app.blade.php
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); // XSS koruması (paylaşılan/dış veri innerHTML'e girmeden)
// ===== TEK GLOBAL inline bildirim (toast) — native alert() yerine app-gibi zarif snackbar. data.js EN ÖNCE yüklenir → tüm modüller (menu/feedback/app) erişir, çift-tanım yok.
// type: 'info'(default)|'ok'|'warn'. ~3sn sonra kaybolur; dokunup kapatılabilir; yenisi gelince eskisini değiştirir.
function toast(msg,type){try{
  if(typeof document==='undefined'||!document.body)return; // headless test ortamı (no-op)
  let host=document.getElementById('besinaiToastHost');
  if(!host){host=document.createElement('div');host.id='besinaiToastHost';host.setAttribute('role','status');host.setAttribute('aria-live','polite');document.body.appendChild(host);}
  const el=document.createElement('div');el.className='bz-toast'+(type==='ok'?' bz-ok':type==='warn'?' bz-warn':'');
  const ic=type==='ok'?'✓':type==='warn'?'⚠️':'ℹ️';
  el.innerHTML='<span class="bz-ic" aria-hidden="true">'+ic+'</span><span class="bz-msg"></span><button type="button" class="bz-x" aria-label="Kapat">✕</button>';
  el.querySelector('.bz-msg').textContent=String(msg==null?'':msg); // textContent → XSS güvenli
  // eski toast'ları temizle (üst üste yığılmasın — tek tutarlı bildirim)
  [...host.children].forEach(c=>{c.classList.add('bz-out');setTimeout(()=>{try{c.remove();}catch(e){}},220);});
  host.appendChild(el);
  requestAnimationFrame(()=>el.classList.add('bz-in'));
  const kill=()=>{el.classList.add('bz-out');setTimeout(()=>{try{el.remove();}catch(e){}},220);};
  el.querySelector('.bz-x').onclick=kill;
  setTimeout(kill,3200);
}catch(e){}}
// Inline onay (confirm() yerine): kart-içi "Sil / Vazgeç" — geri-dönülmez veri silmede kullanıcı kasıtlı dokunmalı. onYes geri-çağrısı.
function confirmInline(msg,onYes){try{
  if(typeof document==='undefined'||!document.body){if(onYes)onYes();return;}
  let host=document.getElementById('besinaiToastHost');
  if(!host){host=document.createElement('div');host.id='besinaiToastHost';host.setAttribute('role','status');document.body.appendChild(host);}
  [...host.children].forEach(c=>{try{c.remove();}catch(e){}});
  const el=document.createElement('div');el.className='bz-toast bz-warn bz-confirm';el.setAttribute('role','alertdialog');
  el.innerHTML='<span class="bz-ic" aria-hidden="true">⚠️</span><span class="bz-msg"></span><span class="bz-acts"><button type="button" class="bz-no">Vazgeç</button><button type="button" class="bz-yes">Sil</button></span>';
  el.querySelector('.bz-msg').textContent=String(msg==null?'':msg);
  host.appendChild(el);requestAnimationFrame(()=>el.classList.add('bz-in'));
  const kill=()=>{el.classList.add('bz-out');setTimeout(()=>{try{el.remove();}catch(e){}},220);};
  el.querySelector('.bz-no').onclick=kill;
  el.querySelector('.bz-yes').onclick=()=>{kill();try{if(onYes)onYes();}catch(e){}};
}catch(e){if(onYes)onYes();}}
