const PREG_RDA={folat:600,demir:27,iyot:220,b12:2.6,cinko:11,avit:770,cvit:85,magnezyum:350,selenyum:60,b6:1.9,kalsiyum:1000};
const LACT_RDA={folat:500,iyot:290,b12:2.8,cinko:12,avit:1300,cvit:120,selenyum:70,b6:2.0,kalsiyum:1000};
function rdaOf(n,sex){const r=RDA_NUM[n];if(r==null)return null;let base=(typeof r==='object')?(sex==='e'?r.e:r.k):r;
  try{const c=(typeof window!=='undefined')&&window.conditions;if(c&&c.has){if(c.has('gebelik')&&PREG_RDA[n]!=null)base=Math.max(base,PREG_RDA[n]);else if(c.has('emzirme')&&LACT_RDA[n]!=null)base=Math.max(base,LACT_RDA[n]);}}catch(e){}
  return base;}
